// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).

use kayak_rt::*;
use super::*;

// compile.kfx: the compiler's entry points, for a program of one file and
// for one of several.
pub fn header() -> Str {
    str_lit("// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).\n\nuse kayak_rt::*;\n\n")
}

pub enum Source {
    Source(Str, Str),
}

pub fn source(f0: Str, f1: Str) -> &'static Source {
    kayak_rt::heap_alloc(Source::Source(f0, f1))
}

pub enum Output {
    Output(Str, Str),
}

pub fn output(f0: Str, f1: Str) -> &'static Output {
    kayak_rt::heap_alloc(Output::Output(f0, f1))
}

pub type Sources = List<&'static Source>;

pub type Outputs = List<&'static Output>;

/// A program checked, then KFX's restrictions (restrict.kfx, C60).
pub fn restrict_checked(checked: &'static Verdict, forms: Sexps) -> &'static Verdict {
    restrictions::restrict(forms);
    checked
}

/// The same, its messages naming `file`; the files it loads, `loaded`.
pub fn compile_named(file: Str, src: Str, loaded: Fileds) -> Str {
    let forms = with_loads(read_all(string_chars(src), file, 1i64), file, loaded);
    let checked = restrict_checked(check_program(forms), forms);
    let c = emitter::collect(forms, ctx(nil::<Str>(), nil::<&'static Tagof>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), verdict_facts(checked), fidx_of(verdict_facts(checked)), nil::<&'static Family>(), nil::<&'static Typed>(), nil::<&'static Typed>()));
    rev_to_string(writing::put_module_impls(c, writing::put_tops(c, forms, writing::put_shapes(c, forms, false, put(header(), nil::<char>())))))
}

/// A program of one file, as Rust, with its top-level expressions as
/// `kfx_toplevel`, which writes their values (emit.kfx).
pub fn compile_toplevel(file: Str, src: Str, loaded: Fileds) -> Str {
    let forms = with_loads(read_all(string_chars(src), file, 1i64), file, loaded);
    let checked = restrict_checked(check_program(forms), forms);
    let c = emitter::collect(forms, ctx(nil::<Str>(), nil::<&'static Tagof>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), verdict_facts(checked), fidx_of(verdict_facts(checked)), nil::<&'static Family>(), nil::<&'static Typed>(), nil::<&'static Typed>()));
    rev_to_string(writing::put_toplevel(c, forms, writing::put_module_impls(c, writing::put_tops(emitter::with_locals(c, kayak_rt::heap_cons(str_lit("%toplevel"), kayak_rt::nil())), forms, writing::put_shapes(c, forms, true, put(header(), nil::<char>()))))))
}

/// A KFX-0 program of one file, as one file of Rust.
pub fn compile(src: Str) -> Str {
    compile_named(str_lit("the program"), src, nil::<&'static Filed>())
}

// Programs of several files. A program is files in order, as a manifest
// (NAME.unit) lists them: to FX-26, the files one after another, so that a
// definition sees those in the files before it. To Rust, a module each,
// which imports every other's names (`use super::*`) and kayak-rt's; the
// modules' `mod.rs` declares them and re-exports their names.

// A file's name, without `.kfx`, and its text; a Rust file's name, and its
// text.
/// A file's forms, the modules made in place defined before theirs (C90).
pub fn source_forms(s: &'static Source) -> Sexps {
    let tagcase_ = s;
    match *tagcase_ {
        Source::Source(name, text) => {
            with_loads(read_all(string_chars(text), string_append(name, str_lit(".kfx")), 1i64), string_append(name, str_lit(".kfx")), nil::<&'static Filed>())
        }
    }
}

pub fn module_header() -> Str {
    str_lit("// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).\n\nuse kayak_rt::*;\nuse super::*;\n\n")
}

pub fn put_mods(ss: Sources, acc: Chars) -> Chars {
    if null_p(ss) {
        acc
    } else {
        let tagcase_ = car(ss);
        match *tagcase_ {
            Source::Source(name, text) => {
                let m = mangle(name);
                let acc = put(str_lit("pub mod "), acc);
                let acc = put(m, acc);
                let acc = put(str_lit(";\npub use "), acc);
                let acc = put(m, acc);
                put_mods(cdr(ss), put(str_lit("::*;\n"), acc))
            }
        }
    }
}

/// A program of several files, as Rust: its modules, then their `mod.rs`.
/// The whole program is checked, and each file written as a module.
pub fn compile_units(ss: Sources) -> Outputs {
    let forms = concat(map(lambda1s(move |s: &'static Source| {
        source_forms(s)
    }), ss));
    let checked = restrict_checked(check_program(forms), forms);
    let c = emitter::collect(forms, ctx(nil::<Str>(), nil::<&'static Tagof>(), nil::<Str>(), nil::<Str>(), verdict_typeds(checked), verdict_facts(checked), fidx_of(verdict_facts(checked)), nil::<&'static Family>(), nil::<&'static Typed>(), nil::<&'static Typed>()));
    let modules = map(lambda1s(move |s: &'static Source| {
        let tagcase_ = s;
        match *tagcase_ {
            Source::Source(name, text) => {
                output(string_append(mangle(name), str_lit(".rs")), rev_to_string(writing::put_tops(c, source_forms(s), put(module_header(), nil::<char>()))))
            }
        }
    }), ss);
    onto(modules, kayak_rt::heap_cons(output(str_lit("mod.rs"), rev_to_string(writing::put_module_impls(c, writing::put_shapes(c, forms, false, put_mods(ss, put(str_lit("// Generated by kfx: the program's modules (PLAN.md, section 1).\n\n"), nil::<char>())))))), kayak_rt::nil()))
}

// A program of several files, as `compile-units`, with memos (incr.kfx,
// C54): those given are taken where they fit, and those this compile made
// or took are given back, for the next.
pub enum Compiled {
    Compiled(Outputs, Memos),
}

pub fn compiled(f0: Outputs, f1: Memos) -> &'static Compiled {
    kayak_rt::heap_alloc(Compiled::Compiled(f0, f1))
}

pub fn memo_modules(mut c: &'static Ctx, mut fs: Facts, mut global: i64, mut old: Memos, mut ss: Sources, mut outs: Outputs, mut made: Memos) -> &'static Compiled {
    loop {
        if null_p(ss) {
            return compiled(reverse_outputs(outs, nil::<&'static Output>()), made);
        } else {
            let tagcase_ = car(ss);
            match *tagcase_ {
                Source::Source(name, text) => {
                    let file = string_append(name, str_lit(".kfx"));
                    let forms = source_forms(car(ss));
                    let starts = map(lambda1s(move |f: &'static Sexp| {
                        datum_pos(f)
                    }), forms);
                    let texts = incremental::form_texts(string_chars(text), 0i64, starts);
                    let tagcase_ = incremental::put_tops_memo(c, incremental::facts_of_file(fs, file), global, old, forms, texts, starts, put(module_header(), nil::<char>()), made);
                    match *tagcase_ {
                        Emitted::Emitted(acc, made2) => {
                            (ss, outs, made) = (cdr(ss), kayak_rt::heap_cons(output(string_append(mangle(name), str_lit(".rs")), rev_to_string(acc)), outs), made2);
                            continue;
                        }
                    }
                }
            }
        }
    }
}

pub fn reverse_outputs(mut xs: Outputs, mut acc: Outputs) -> Outputs {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc) = (cdr(xs), kayak_rt::heap_cons(car(xs), acc));
            continue;
        }
    }
}

/// Each of a file's forms' text (incr.kfx).
pub fn source_texts(s: &'static Source) -> Strings {
    let tagcase_ = s;
    match *tagcase_ {
        Source::Source(name, text) => {
            incremental::form_texts(string_chars(text), 0i64, map(lambda1s(move |f: &'static Sexp| {
                datum_pos(f)
            }), source_forms(s)))
        }
    }
}

pub fn compile_units_memo(ss: Sources, old: Memos) -> &'static Compiled {
    let forms = concat(map(lambda1s(move |s: &'static Source| {
        source_forms(s)
    }), ss));
    let texts = concat(map(&source_texts, ss));
    let tagcase_ = {
        let c = incremental::check_program_memo(forms, texts, old);
        restrictions::restrict(forms);
        c
    };
    match *tagcase_ {
        CheckedMemo::CheckedMemo(done, found, checks) => {
            let c = emitter::collect(forms, ctx(nil::<Str>(), nil::<&'static Tagof>(), nil::<Str>(), nil::<Str>(), found, cv_facts(done), fidx_of(cv_facts(done)), nil::<&'static Family>(), nil::<&'static Typed>(), nil::<&'static Typed>()));
            let tagcase_ = memo_modules(c, cv_facts(done), incremental::ctx_fingerprint(c), old, ss, nil::<&'static Output>(), checks);
            match *tagcase_ {
                Compiled::Compiled(modules, made) => {
                    compiled(onto(modules, kayak_rt::heap_cons(output(str_lit("mod.rs"), rev_to_string(writing::put_module_impls(c, writing::put_shapes(c, forms, false, put_mods(ss, put(str_lit("// Generated by kfx: the program's modules (PLAN.md, section 1).\n\n"), nil::<char>())))))), kayak_rt::nil())), made)
                }
            }
        }
    }
}

/// Outputs as one string, for stage 0, where Fixpt prints one: each a line
/// `@@kfx-file NAME`, then its text. No line of generated Rust starts with
/// `@@`, since its string literals hold no newline but escaped.
pub fn bundle(os: Outputs) -> Str {
    if null_p(os) {
        str_lit("")
    } else {
        let tagcase_ = car(os);
        match *tagcase_ {
            Output::Output(name, text) => {
                string_append(str_lit("@@kfx-file "), string_append(name, string_append(str_lit("\n"), string_append(text, bundle(cdr(os))))))
            }
        }
    }
}

